const base={status:'verified',tenantName:'Verified tenant — missing code',propertyName:'KLB',roomName:'Room 7',billMonth:'2026-09-01',paymentDate:'2026-09-01',amountSubmitted:'RM 100.00',amountSubmittedValue:100,paymentPurpose:'monthly_rent',invoiceOutstanding:100,rentOutstanding:100,depositOutstanding:0,referenceNumber:'',receiptIsImage:true,receiptUrl:'/slip.svg'};
const rows=[{...base,submissionId:'old'},{...base,submissionId:'existing',tenantName:'Verified tenant — existing QR',referenceNumber:'QR00027588'},{...base,submissionId:'pending',status:'pending_verification',tenantName:'Awaiting tenant'},{...base,submissionId:'duplicate',tenantName:'Duplicate test tenant'}];
createRoot(document.getElementById('root')).render(<main className="m-6 rounded-xl border bg-white p-5"><h1 className="mb-2 text-2xl font-semibold">Payment Verification — test data only</h1><p className="mb-6">One row per slip. Save a missing bank code without re-verifying.</p><Table><TableHeader><TableRow>{['Slip','Tenant','Property / Room','Rental month','Amount','Bank code','Method','Status','Action'].map(x=><TableHead key={x}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.map(row=><PaymentSlipRow key={row.submissionId} row={row} paymentMethod="bank_transfer" canCorrectPurpose={false} canReverse={false} returnTo="/verification?view=payments" errorMessages={{}}/>)}</TableBody></Table></main>);
